# ── NaN/Inf-safe JSON ─────────────────────────────────────────────────────────
# Postgres float columns and numpy computations can yield NaN/Infinity. Python's
# default json emits the literal tokens `NaN`/`Infinity`, which are INVALID JSON —
# the browser's JSON.parse throws and the tab spins forever ("Load failed"). This
# provider recursively replaces NaN/Inf with null so every response is valid JSON.
# Wrapped in try/except so it can never itself break a response.
import math as _math_san
from flask.json.provider import DefaultJSONProvider as _DefaultJSONProvider

def _json_sanitize(o):
    if isinstance(o, float):
        return None if (_math_san.isnan(o) or _math_san.isinf(o)) else o
    # numpy scalars (float32/float64) inherit from float above, but Decimal does not.
    # psycopg2 NUMERIC/FLOAT8 columns can carry Decimal("NaN") — convert and check.
    try:
        import decimal as _dec_san
        if isinstance(o, _dec_san.Decimal):
            try:
                f = float(o)
                return None if (_math_san.isnan(f) or _math_san.isinf(f)) else f
            except Exception:
                return None
    except Exception:
        pass
    if isinstance(o, dict):
        return {k: _json_sanitize(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [_json_sanitize(v) for v in o]
    return o

class _SafeJSONProvider(_DefaultJSONProvider):
    def dumps(self, obj, **kwargs):
        try:
            obj = _json_sanitize(obj)
        except Exception:
            pass
        return super().dumps(obj, **kwargs)

app.json = _SafeJSONProvider(app)


@app.after_request
def _no_store_api(resp):
    """Force dynamic API responses to never be cached by the browser/proxy.
    Without this, identical GET URLs get served from disk/CDN cache and the
    UI shows stale (e.g. yesterday's) data even though the server is fresh."""
    try:
        if request.path.startswith("/stock-api"):
            resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
            resp.headers["Pragma"] = "no-cache"
            resp.headers["Expires"] = "0"
    except Exception:
        pass
    return resp


_last_owner_catchup_ts = 0.0


@app.before_request
def _owner_catchup_on_wake():
    """Backup for Autoscale (which sleeps and misses scheduled emails): when ANY
    request wakes this server — e.g. the owner opens the site in the morning — fire
    the catch-up in the background so today's due-but-unsent owner emails go out.
    Throttled + non-blocking so it never slows a request. Harmless on a Reserved VM:
    the owner_email_log claims dedupe it against the real-time scheduler."""
    global _last_owner_catchup_ts
    try:
        # Skip CORS preflights and the manual catch-up endpoint (which runs the
        # catch-up itself) so we never double-trigger the same window.
        if request.method == "OPTIONS" or request.path == "/stock-api/admin/owner-catchup":
            return
        import time as _t_bw
        _now_bw = _t_bw.time()
        if _now_bw - _last_owner_catchup_ts < 120:
            return
        _last_owner_catchup_ts = _now_bw
        import threading as _th_bw
        _th_bw.Thread(target=_owner_run_due_emails, daemon=True).start()
    except Exception:
        pass


_last_news_catchup_ts = 0.0


@app.before_request
def _news_catchup_on_wake():
    """Backup for the NEWS CATALYST alert emails. The scheduled news scans run
    9:31–10:30 ET, but on Autoscale a sleeping server misses them — the owner saw a
    catalyst email land at 10:44 instead of in the 9:31 window. So when ANY request
    wakes the server during the trading day, fire a fresh news-catalyst scan in the
    background. run_news_catalyst_scan dedupes per-ticker via its own log table, so a
    re-run only ever emails NEW catalysts — never a duplicate. Throttled + non-blocking
    so it never slows a request; harmless on a Reserved VM (the dedup log guards it
    against the real-time scheduler)."""
    global _last_news_catchup_ts
    try:
        if request.method == "OPTIONS" or request.path == "/stock-api/admin/news-catchup":
            return
        from datetime import datetime as _dt_nw
        _now_et = _dt_nw.now(_ET_TZ)
        if _now_et.weekday() >= 5:                       # weekdays only
            return
        _cur_min = _now_et.hour * 60 + _now_et.minute
        # From the first scheduled slot (9:31) through the close (16:00 ET). A monster
        # news mover is still worth catching at 11am or 1pm if the morning was missed.
        if _cur_min < 9 * 60 + 31 or _cur_min > 16 * 60:
            return
        import time as _t_nw
        _now_ts = _t_nw.time()
        if _now_ts - _last_news_catchup_ts < 300:        # at most once every 5 min
            return
        _last_news_catchup_ts = _now_ts
        import threading as _th_nw
        _th_nw.Thread(target=_news_run_due_scan, daemon=True).start()
    except Exception:
        pass


_NTFY_TOPIC = "stockscanner-joel-9x7k2"

def _send_ntfy(title: str, body: str, priority: str = "high", tags: str = "bell") -> bool:
    """Send a push notification via ntfy.sh — never raises. Returns True on 2xx."""
    try:
        import requests as _r
        _resp = _r.post(
            f"https://ntfy.sh/{_NTFY_TOPIC}",
            data=body.encode("utf-8"),
            headers={"Title": title, "Priority": priority, "Tags": tags},
            timeout=8,
        )
        return 200 <= _resp.status_code < 300
    except Exception as _ne:
        print(f"[ntfy] error: {_ne}")
        return False

# ── Global yfinance HTTP timeout patch ────────────────────────────────────────
# yfinance creates requests.Session internally and never sets per-request
# timeouts, so rate-limited calls hang forever and block Flask worker threads.
# Patching Session.__init__ here ensures every Session (including yfinance's)
# mounts an adapter that enforces an 8-second timeout on each HTTP call.
# Yahoo Finance circuit breaker: when Yahoo rate-limits (HTTP 429/503), trip a
# short global cooldown so subsequent yfinance HTTP calls fail FAST instead of
# hanging (and piling up on Flask worker threads). Tab endpoints then fall back
# to cached/DB snapshots quickly rather than spinning forever. Scoped to Yahoo
# hosts only — OpenAI/Anthropic/Stripe/Finviz traffic is untouched.
import time as _time_cb
# ── Yahoo circuit breaker with half-open recovery (single-probe) ─────────────
# When Yahoo throttles, the breaker trips → all calls fail fast for a cooldown.
# When cooldown expires, it enters "half-open" and allows ONE probe call.
# If the probe succeeds, the breaker closes fully. If it fails, it reopens.
# This prevents the "all threads rush at once" spiral that keeps the breaker
# stuck open all day.

_YF_BREAKER = {"state": "closed", "until": 0.0, "probing": False}
_YF_BREAKER_COOLDOWN = 60.0   # seconds to stay "open" after a rate-limit hit (1 min; re-trips if load is still high)
_YF_BREAKER_LOCK = threading.Lock()

# ── Global yfinance rate limiter (token bucket) ──────────────────────────────
# Caps ALL yfinance HTTP calls at 3/second across every thread and every job.
# This is the primary defence against Yahoo throttling — no burst is possible.
class _YFRateLimiter:
    def __init__(self, calls_per_sec: float = 3.0):
        self._lock   = threading.Lock()
        self._tokens = calls_per_sec
        self._max    = calls_per_sec
        self._rate   = calls_per_sec
        self._last   = _time_cb.monotonic()
    def acquire(self):
        while True:
            with self._lock:
                now = _time_cb.monotonic()
                self._tokens = min(self._max, self._tokens + (now - self._last) * self._rate)
                self._last = now
                if self._tokens >= 1.0:
                    self._tokens -= 1.0
                    return
            _time_cb.sleep(0.05)

_YF_RATE_LIMITER = _YFRateLimiter(calls_per_sec=3.0)

def _yf_breaker_state() -> str:
    """Return current breaker state: 'closed', 'open', or 'half-open'."""
    now = _time_cb.time()
    with _YF_BREAKER_LOCK:
        state = _YF_BREAKER["state"]
        if state == "closed":
            return "closed"
        if state == "open" and now < _YF_BREAKER["until"]:
            return "open"
        if state == "open" and now >= _YF_BREAKER["until"]:
            # Transition to half-open: exactly one probe allowed
            _YF_BREAKER["state"] = "half-open"
            _YF_BREAKER["probing"] = False
            return "half-open"
        if state == "half-open":
            return "half-open"
        # Fallback to closed
        _YF_BREAKER["state"] = "closed"
        return "closed"

def _yf_breaker_acquire_probe() -> bool:
    """In half-open: grant the single probe token to one caller. Thread-safe."""
    with _YF_BREAKER_LOCK:
        if _YF_BREAKER["state"] != "half-open":
            return False
        if _YF_BREAKER["probing"]:
            return False  # Another thread is already probing
        _YF_BREAKER["probing"] = True
        return True

def _yf_breaker_probe_success() -> None:
    """Probe call succeeded → breaker fully closes."""
    with _YF_BREAKER_LOCK:
        _YF_BREAKER["state"] = "closed"
        _YF_BREAKER["probing"] = False

def _yf_breaker_probe_failure() -> None:
    """Probe call failed → breaker reopens for cooldown."""
    with _YF_BREAKER_LOCK:
        _YF_BREAKER["state"] = "open"
        _YF_BREAKER["until"] = _time_cb.time() + _YF_BREAKER_COOLDOWN
        _YF_BREAKER["probing"] = False

def _yf_breaker_trip() -> None:
    """Force trip the breaker (rate-limit hit, 401 burst, etc.)."""
    with _YF_BREAKER_LOCK:
        _YF_BREAKER["state"] = "open"
        _YF_BREAKER["until"] = _time_cb.time() + _YF_BREAKER_COOLDOWN
        _YF_BREAKER["probing"] = False

def _yf_breaker_open() -> bool:
    """Legacy compatibility: returns True if breaker is NOT closed."""
    return _yf_breaker_state() != "closed"

class _YFBreakerCompat:
    """Thin shim so _yahoo_breaker.allow() / .record_success() / .record_failure()
    calls route through the single shared _YF_BREAKER state.  Previously these
    names were used in market_overview and squeeze_setup background threads but
    never defined — causing a silent NameError that prevented both scans from ever
    completing (tabs spun forever)."""
    def allow(self) -> bool:  return not _yf_breaker_open()
    def record_success(self): _yf_breaker_probe_success()
    def record_failure(self): _yf_breaker_trip()
_yahoo_breaker = _YFBreakerCompat()

# Yahoo also throttles via HTTP 401 "Unauthorized" / "Invalid Crumb" floods. These
# are NOT 429/503 and NOT exceptions — they're returned responses that yfinance
# silently swallows as "no data" (hence the "$X possibly delisted" log spam), so
# the breaker above never trips and scans churn through hundreds of slow 401s.
# A single 401 can be a benign crumb refresh, so we only trip on a sustained BURST.
_YF_AUTH_HITS: list = []          # timestamps of recent Yahoo 401/403 responses
_YF_AUTH_LOCK = threading.Lock()
_YF_AUTH_WINDOW = 20.0            # seconds to remember 401/403 hits
_YF_AUTH_THRESHOLD = 5           # this many 401/403 within the window trips breaker

def _yf_note_auth_throttle() -> None:
    now = _time_cb.time()
    with _YF_AUTH_LOCK:
        _YF_AUTH_HITS.append(now)
        _cutoff = now - _YF_AUTH_WINDOW
        while _YF_AUTH_HITS and _YF_AUTH_HITS[0] < _cutoff:
            _YF_AUTH_HITS.pop(0)
        if len(_YF_AUTH_HITS) >= _YF_AUTH_THRESHOLD:
            _yf_breaker_trip()
            _YF_AUTH_HITS.clear()

# Silent-throttle detector: yfinance swallows Yahoo 401s/throttles as empty
# DataFrames ("possibly delisted") so the HTTP-level breaker above never trips.
# Track empty-price / empty-options results from scan workers; if 15+ within
# 30 s, Yahoo is clearly throttling and we trip the breaker so the rest of the
# scan fails fast instead of churning for 3+ minutes.
_YF_SILENT_HITS: list = []
_YF_SILENT_LOCK = threading.Lock()
_YF_SILENT_WINDOW = 30.0
_YF_SILENT_THRESHOLD = 15

def _yf_note_silent_throttle() -> None:
    now = _time_cb.time()
    with _YF_SILENT_LOCK:
        _YF_SILENT_HITS.append(now)
        _cutoff = now - _YF_SILENT_WINDOW
        while _YF_SILENT_HITS and _YF_SILENT_HITS[0] < _cutoff:
            _YF_SILENT_HITS.pop(0)
        if len(_YF_SILENT_HITS) >= _YF_SILENT_THRESHOLD:
            _yf_breaker_trip()
            _YF_SILENT_HITS.clear()
            print("[breaker] silent-throttle tripped: 15+ empty price/options responses in 30s")

try:
    import requests as _req_patch
    from requests.adapters import HTTPAdapter as _HTTPAdapter
    from requests.exceptions import ConnectionError as _ReqConnErr

    class _TimeoutAdapter(_HTTPAdapter):
        def send(self, request, *args, **kwargs):
            _url = getattr(request, "url", "") or ""
            _is_yahoo = "yahoo.com" in _url
            _state = None
            if _is_yahoo:
                _state = _yf_breaker_state()
                if _state == "open":
                    # Breaker open: back off briefly (releasing the GIL) before
                    # failing, so scan worker threads don't hot-loop through the
                    # whole universe and starve the Flask HTTP threads of CPU.
                    _time_cb.sleep(0.05)
                    raise _ReqConnErr("yfinance circuit breaker open (Yahoo rate-limited)")
                if _state == "half-open":
                    # Exactly one probe thread allowed through; others wait.
                    _is_probe = _yf_breaker_acquire_probe()
                    if not _is_probe:
                        _time_cb.sleep(0.05)
                        raise _ReqConnErr("yfinance circuit breaker half-open (probe in progress)")
                if kwargs.get("timeout") is None:
                    kwargs["timeout"] = 8
            else:
                kwargs.setdefault("timeout", 8)
            _resp = super().send(request, *args, **kwargs)
            try:
                if _is_yahoo:
                    _sc = _resp.status_code
                    if _sc in (429, 503):
                        _yf_breaker_trip()
                    elif _sc in (401, 403):
                        _yf_note_auth_throttle()
                    elif _state == "half-open" and _sc < 400:
                        _yf_breaker_probe_success()
            except Exception:
                pass
            return _resp

    _orig_session_init = _req_patch.Session.__init__
    def _patched_session_init(self, *args, **kwargs):
        _orig_session_init(self, *args, **kwargs)
        self.mount("https://", _TimeoutAdapter())
        self.mount("http://",  _TimeoutAdapter())
    _req_patch.Session.__init__ = _patched_session_init
    print("[startup] global requests timeout adapter + Yahoo circuit breaker installed")
except Exception as _tpe:
    print(f"[startup] timeout adapter failed (non-fatal): {_tpe}")

# yfinance 1.4.1 fetches from Yahoo via curl_cffi (browser TLS impersonation),
# NOT requests — so the adapter above does NOT cover it. yfinance also hard-codes
# timeout=30s per call, so when Yahoo is slow the dashboard tabs hang ~30s and the
# spinner never resolves. This patch wraps curl_cffi's Session.request to, for
# yahoo.com URLs only: (a) cap the per-call timeout to 8s, and (b) trip the shared
# global circuit breaker on rate-limit (429/503) or timeout so that subsequent
# Yahoo calls fail INSTANTLY for a short cooldown — endpoints then fall back to
# cached/DB data in <1s instead of spinning. Non-Yahoo curl_cffi traffic (if any)
# is passed through untouched.
try:
    from curl_cffi import requests as _cffi_req
    from curl_cffi.requests import RequestsError as _CffiErr
    _YF_YAHOO_TIMEOUT = 8.0
    _cffi_orig_request = _cffi_req.Session.request

    def _cffi_patched_request(self, method, url, *args, **kwargs):
        _u = str(url or "")
        if "yahoo.com" not in _u:
            return _cffi_orig_request(self, method, url, *args, **kwargs)
        if _yf_breaker_open():
            # Back off (releasing the GIL) so scan worker threads don't hot-loop
            # and starve the Flask HTTP threads while Yahoo is throttling — keeps
            # the dashboard tabs loading from cache/DB instead of erroring out.
            _time_cb.sleep(0.05)
            raise _CffiErr("yfinance circuit breaker open (Yahoo rate-limited)")
        # Rate-limit EVERY Yahoo HTTP call globally — prevents bursts from any job.
        # 3 req/sec sustained means ~180/min across ALL background threads combined.
        _YF_RATE_LIMITER.acquire()
        _t = kwargs.get("timeout", None)
        if not (isinstance(_t, (int, float)) and not isinstance(_t, bool) and _t <= _YF_YAHOO_TIMEOUT):
            kwargs["timeout"] = _YF_YAHOO_TIMEOUT
        try:
            _resp = _cffi_orig_request(self, method, url, *args, **kwargs)
        except Exception:
            # Timeout or connection error — trip the breaker so subsequent calls
            # fail fast and free up threads for the Flask HTTP workers.
            with _YF_BREAKER_LOCK:
                _YF_BREAKER["state"] = "open"
                _YF_BREAKER["until"] = _time_cb.time() + _YF_BREAKER_COOLDOWN
                _YF_BREAKER["probing"] = False
            raise
        try:
            _sc = getattr(_resp, "status_code", 0)
            if _sc in (429, 503):
                with _YF_BREAKER_LOCK:
                    _YF_BREAKER["state"] = "open"
                    _YF_BREAKER["until"] = _time_cb.time() + _YF_BREAKER_COOLDOWN
                    _YF_BREAKER["probing"] = False
            elif _sc in (401, 403):
                _yf_note_auth_throttle()
        except Exception:
            pass
        return _resp

    _cffi_req.Session.request = _cffi_patched_request
    print("[startup] curl_cffi Yahoo timeout cap (8s) + circuit breaker installed")
except Exception as _ce:
    print(f"[startup] curl_cffi patch failed (non-fatal): {_ce}")

