@app.route("/stock-api/unusual-calls", methods=["GET"])
def unusual_calls():
    """Scan for unusual near-term call activity (1-30 days) with Vol/OI >= 3x — pure bullish bets, not hedges."""
    from concurrent.futures import ThreadPoolExecutor, as_completed
    import yfinance as yf
    from datetime import datetime as _dt
    import threading

    # Ensure a single scan lock exists
    if not hasattr(app, "_uc_lock"):
        app._uc_lock = threading.Lock()

    cache_only = str(request.args.get("cache_only", "")).lower() in ("1", "true", "yes")

    _cache = getattr(app, "_unusual_calls_cache", None)
    _ts    = getattr(app, "_unusual_calls_cache_ts", None)
    if _cache and _ts and (_dt.now() - _ts).total_seconds() < 900:
        return jsonify(_cache)

    # Lightweight callers (e.g. the 8:30 premarket brief) pass cache_only=1 to avoid
    # triggering a cold full option-chain scan: serve the in-memory cache if fresh
    # (handled above), else TODAY's DB rows (ET day), else empty — never scan live.
    if cache_only:
        try:
            with _psycopg2.connect(_DB_URL) as _co_conn, _co_conn.cursor() as _co_cur:
                _co_cur.execute("""
                    SELECT ticker, price::float, strike::float, expiry, days_out,
                           volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
                           iv::float, urgency, first_seen
                    FROM unusual_calls_log
                    WHERE last_seen >= (date_trunc('day', now() AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York') AT TIME ZONE 'UTC'
                      AND expiry::date > (now() AT TIME ZONE 'America/New_York')::date
                      AND vol_oi >= 3
                      AND prem >= 500000
                    ORDER BY last_seen DESC, vol_oi DESC LIMIT 80
                """)
                _co_rows = _co_cur.fetchall()
            _cols = ["ticker","price","strike","expiry","days_out","volume","oi","vol_oi","prem","otm_pct","iv","urgency","first_seen"]
            _hits = []
            for _row in _co_rows:
                _d = dict(zip(_cols, _row))
                _fs = _d.get("first_seen")
                _d["detected_label"] = _detected_label(_fs)
                _d["first_seen"] = _fs.isoformat() if _fs else None
                _hits.append(_d)
            return jsonify({"hits": _hits, "total": len(_hits), "scanned": 0, "cache_only": True})
        except Exception as _e:
            return jsonify({"hits": [], "total": 0, "scanned": 0, "cache_only": True, "error": str(_e)})

    # Outside market hours (weekends/after-hours) there is no live option chain data
    # to scan — serve from DB directly instead of hanging on Yahoo.
    # Use a 5-day lookback so Friday's sweeps remain visible all weekend.
    if not _intraday_scan_allowed():
        try:
            with _psycopg2.connect(_DB_URL) as _nh_conn, _nh_conn.cursor() as _nh_cur:
                _nh_cur.execute("""
                    SELECT ticker, price::float, strike::float, expiry, days_out,
                           volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
                           iv::float, urgency, first_seen
                    FROM unusual_calls_log
                    WHERE last_seen >= now() - INTERVAL '5 days'
                      AND expiry::date > (now() AT TIME ZONE 'America/New_York')::date
                      AND vol_oi >= 3 AND prem >= 500000
                    ORDER BY last_seen DESC, vol_oi DESC LIMIT 80
                """)
                _nh_rows = _nh_cur.fetchall()
            _nh_cols = ["ticker","price","strike","expiry","days_out","volume","oi",
                        "vol_oi","prem","otm_pct","iv","urgency","first_seen"]
            _nh_hits = []
            for _row in _nh_rows:
                _d = dict(zip(_nh_cols, _row))
                _fs = _d.get("first_seen")
                _d["detected_label"] = _detected_label(_fs)
                _d["first_seen"] = _fs.isoformat() if _fs else None
                _nh_hits.append(_d)
            _nh_out = {"hits": _nh_hits, "total": len(_nh_hits), "scanned": 0,
                       "stale": True, "note": "market closed — showing last logged sweep data"}
            app._unusual_calls_cache    = _nh_out
            app._unusual_calls_cache_ts = _dt.now()
            return jsonify(_nh_out)
        except Exception as _nh_e:
            return jsonify({"hits": [], "total": 0, "scanned": 0, "stale": True,
                            "error": str(_nh_e)})

    # Only one scan at a time — concurrent requests block here until the scan
    # finishes, then the re-check returns the fresh cache instead of re-scanning.
    with app._uc_lock:
        # Re-check after acquiring lock — another thread may have just finished
        _cache = getattr(app, "_unusual_calls_cache", None)
        _ts    = getattr(app, "_unusual_calls_cache_ts", None)
        if _cache and _ts and (_dt.now() - _ts).total_seconds() < 900:
            return jsonify(_cache)

        # Breaker open → serve DB snapshot immediately instead of a live scan
        if _yf_breaker_open():
            try:
                with _psycopg2.connect(_DB_URL) as _ub_conn, _ub_conn.cursor() as _ub_cur:
                    _ub_cur.execute("""
                        SELECT ticker, price::float, strike::float, expiry, days_out,
                               volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
                               iv::float, urgency, first_seen
                        FROM unusual_calls_log
                        WHERE last_seen >= now() - INTERVAL '5 days'
                          AND expiry::date > (now() AT TIME ZONE 'America/New_York')::date
                          AND vol_oi >= 2
                          AND prem >= 200000
                        ORDER BY last_seen DESC, vol_oi DESC LIMIT 80
                    """)
                    _ub_rows = _ub_cur.fetchall()
                _cols = ["ticker","price","strike","expiry","days_out","volume","oi","vol_oi","prem","otm_pct","iv","urgency","first_seen"]
                _ub_hits = []
                for _row in _ub_rows:
                    _d = dict(zip(_cols, _row))
                    _fs = _d.get("first_seen")
                    _d["detected_label"] = _detected_label(_fs)
                    _d["first_seen"] = _fs.isoformat() if _fs else None
                    _ub_hits.append(_d)
                return jsonify({"hits": _ub_hits, "total": len(_ub_hits), "scanned": 0,
                                "note": "stale — Yahoo throttled, serving DB snapshot", "stale": True})
            except Exception as _ube:
                return jsonify({"hits": [], "total": 0, "scanned": 0, "stale": True,
                                "note": f"breaker open, DB fallback failed: {_ube}"})

        now = _dt.now()

        # ETF tickers get calibrated thresholds: lower vol/OI (they carry massive OI) and
        # wider expiry window (institutional ETF plays tend to go 30-60 days out).
        _ETF_SET = {
            "SPY","QQQ","IWM","DIA","MDY","VTI","VOO",
            "XLF","XLE","XLK","XLY","XLI","XLV","XLB","XLP","XLU","XLRE",
            "SMH","SOXX","XBI","IBB","KRE","XRT","ITB","JETS","KWEB","DRAM",
            "TQQQ","SPXL","SOXL","UDOW","LABU","FNGU","TECL","UPRO","TNA","FAS","ERX",
            "SQQQ","SPXS","SOXS","SDOW","TZA","FAZ","ERY",
            "SSO","QLD","DDM","UWM","SDS","QID","DXD","TWM",
            "VXX","UVXY","SVXY","VIXY","SVOL",
            "GLD","IAU","SLV","USO","UNG","GDX","GDXJ","OIH",
            "TLT","HYG","LQD","TBT","TMF","SHY","IEF","JNK",
            "EEM","EFA","FXI","EWJ","EWZ","EWY","IEMG",
            "ARKK","ARKG","ARKW","ARKF",
            "IBIT","FBTC","BITB","ARKB","WGMI",
        }

        def _scan_unusual(ticker):
            hits    = []
            is_etf  = ticker in _ETF_SET
            # ETFs: $50K floor (high liquidity); stocks: $20K catches small-cap insider bets
            min_voi  = 1.5  if is_etf else 2.0
            min_prem = 50_000 if is_etf else 20_000
            max_days = 60   if is_etf else 45
            try:
                tkr   = yf.Ticker(ticker)
                price = float(getattr(tkr.fast_info, "last_price", 0) or 0)
                if price <= 0: return hits
                exps = tkr.options
                if not exps: return hits
                for exp in exps:
                    try:
                        days_out = (_dt.strptime(exp, "%Y-%m-%d") - now).days
                        if not (1 <= days_out <= max_days): continue
                        calls = tkr.option_chain(exp).calls
                        for _, row in calls.iterrows():
                            strike = float(row.get("strike", 0) or 0)
                            vol    = int(row.get("volume", 0) or 0)
                            oi     = int(row.get("openInterest", 0) or 0)
                            last   = float(row.get("lastPrice", 0) or 0)
                            iv     = float(row.get("impliedVolatility", 0) or 0)
                            if strike <= 0 or last <= 0 or vol < 10: continue
                            if strike < price * 0.15: continue
                            pre_otm = (strike - price) / price * 100
                            if pre_otm < -15: continue   # skip deep ITM — hedges
                            if pre_otm > 50: continue    # skip lottery-ticket far OTM
                            vol_oi = round(vol / max(oi, 1), 2)
                            if vol_oi < min_voi: continue
                            prem = round(vol * last * 100, 0)
                            if prem < min_prem: continue
                            urgency = "EXPIRING" if days_out <= 7 else "NEAR" if days_out <= 14 else "SHORT"
                            # pre_positioned: OI >> vol = accumulated BEFORE today (quiet insider pattern)
                            pre_positioned = bool(oi >= 100 and vol < oi * 0.5)
                            ldt = row.get("lastTradeDate")
                            last_trade = str(ldt)[:10] if ldt is not None else ""
                            hits.append({
                                "ticker":          ticker,
                                "price":           round(price, 2),
                                "strike":          round(strike, 2),
                                "expiry":          exp,
                                "days_out":        days_out,
                                "volume":          vol,
                                "oi":              oi,
                                "vol_oi":          vol_oi,
                                "prem":            int(prem),
                                "otm_pct":         round(pre_otm, 1),
                                "iv":              round(iv * 100, 1),
                                "urgency":         urgency,
                                "pre_positioned":  pre_positioned,
                                "last_trade":      last_trade,
                                "is_etf":          is_etf,
                            })
                    except Exception: continue
            except Exception: pass
            return hits

        # Check DB for TODAY's data first (ET calendar day) — avoids a slow live
        # scan if today already has results. Must be ET-today, NOT a rolling
        # window: a rolling 36h pre-check would serve yesterday's rows as "today's"
        # on this live/current tab (which shows no per-row dates).
        try:
            with _psycopg2.connect(_DB_URL) as _pre_conn, _pre_conn.cursor() as _pre_cur:
                _pre_cur.execute("""
                    SELECT ticker, price::float, strike::float, expiry, days_out,
                           volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
                           iv::float, urgency, first_seen
                    FROM unusual_calls_log
                    WHERE last_seen >= (date_trunc('day', now() AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York') AT TIME ZONE 'UTC'
                      AND expiry::date > (now() AT TIME ZONE 'America/New_York')::date
                      AND vol_oi >= 3
                      AND prem >= 500000
                    ORDER BY last_seen DESC, vol_oi DESC LIMIT 80
                """)
                _today_rows = _pre_cur.fetchall()
            if len(_today_rows) >= 5:
                _cols = ["ticker","price","strike","expiry","days_out","volume","oi","vol_oi","prem","otm_pct","iv","urgency","first_seen"]
                all_hits = []
                for _row in _today_rows:
                    _d = dict(zip(_cols, _row))
                    _d["is_etf"] = _d["ticker"] in _ETF_SET
                    _fs = _d.get("first_seen")
                    _d["detected_label"] = _detected_label(_fs)
                    _d["first_seen"] = _fs.isoformat() if _fs else None
                    all_hits.append(_d)
                out = {"hits": all_hits, "total": len(all_hits),
                       "scanned": len(DEFAULT_LEADERBOARD), "stale": False}
                app._unusual_calls_cache    = out
                app._unusual_calls_cache_ts = _dt.now()
                return jsonify(out)
        except Exception:
            pass

        # Live scan — movers first so earnings/catalyst stocks are always caught,
        # then fill with the core leaderboard. Stocks up 5%+ (like CBRL +24%)
        # appear in day_gainers and get scanned regardless of leaderboard position.
        _movers = _fetch_market_movers()
        _mover_set = set(_movers)
        _scan_universe = _movers + [t for t in DEFAULT_LEADERBOARD[:400] if t not in _mover_set]

        all_hits = []
        with ThreadPoolExecutor(max_workers=20) as ex:
            futures = {ex.submit(_scan_unusual, t): t for t in _scan_universe}
            for fut in as_completed(futures):
                all_hits.extend(fut.result() or [])

        all_hits.sort(key=lambda x: x["vol_oi"], reverse=True)

        # If live scan returned nothing (rate limited / cold start), fall back to
        # saved DB rows so the tab is never blank: prefer TODAY's rows; if today is
        # also empty (e.g. the data feed was throttled all morning), show the most
        # recent saved activity (last 7 days) flagged as stale. Each row keeps its
        # real detected-date label, so older names are clearly dated.
        _stale_fallback = False
        if not all_hits:
            try:
                with _psycopg2.connect(_DB_URL) as _conn, _conn.cursor() as _cur:
                    _cur.execute("""
                        SELECT ticker, price::float, strike::float, expiry, days_out,
                               volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
                               iv::float, urgency, first_seen
                        FROM unusual_calls_log
                        WHERE last_seen >= (date_trunc('day', now() AT TIME ZONE 'America/New_York') AT TIME ZONE 'America/New_York') AT TIME ZONE 'UTC'
                          AND vol_oi >= 3
                          AND prem >= 100000
                        ORDER BY vol_oi DESC LIMIT 80
                    """)
                    _fb_rows = _cur.fetchall()
                    if len(_fb_rows) < 5:
                        # Today is empty — or only a sparse row or two slipped in
                        # (the prod blank-tab failure mode) — so show the most recent
                        # saved names instead of a near-blank tab. The 7-day query is
                        # ORDER BY last_seen DESC, so any of today's rows still sort to
                        # the top. Flagged stale; never re-saved (would corrupt dates).
                        _cur.execute("""
                            SELECT ticker, price::float, strike::float, expiry, days_out,
                                   volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
                                   iv::float, urgency, first_seen
                            FROM unusual_calls_log
                            WHERE last_seen >= NOW() - INTERVAL '7 days'
                              AND vol_oi >= 3
                              AND prem >= 100000
                            ORDER BY last_seen DESC, vol_oi DESC LIMIT 80
                        """)
                        _fb_rows = _cur.fetchall()
                        _stale_fallback = bool(_fb_rows)
                    _cols = ["ticker","price","strike","expiry","days_out","volume","oi","vol_oi","prem","otm_pct","iv","urgency","first_seen"]
                    for _row in _fb_rows:
                        _d = dict(zip(_cols, _row))
                        _d["is_etf"] = _d["ticker"] in _ETF_SET
                        _fs = _d.get("first_seen")
                        _d["detected_label"] = _detected_label(_fs)
                        _d["first_seen"] = _fs.isoformat() if _fs else None
                        all_hits.append(_d)
            except Exception:
                pass

        # Save FIRST so each hit dict is stamped in-place with first_seen /
        # detected_label, THEN build + cache out — otherwise a concurrent request
        # could read a cached response before the date badges are attached.
        # NEVER re-save the stale (older-day) fallback rows — that would re-stamp
        # last_seen to today and corrupt the "detected" dates.
        if all_hits and not _stale_fallback:
            _save_unusual_calls_to_db(all_hits)
            # Serve the full day's accumulated sweeps — earlier scans' results
            # remain visible even after a newer scan runs.
            _today_all = _load_todays_unusual_calls_from_db(_ETF_SET)
            if _today_all:
                all_hits = _today_all
        out = {"hits": all_hits[:150], "total": len(all_hits),
               "scanned": len(DEFAULT_LEADERBOARD), "stale": _stale_fallback}
        if _stale_fallback:
            out["note"] = ("No new unusual calls have come through yet today (data feed quiet) — "
                           "showing the most recent saved activity.")
        app._unusual_calls_cache    = out
        app._unusual_calls_cache_ts = _dt.now()
        if _stale_fallback:
            # Expire the stale cache quickly (~3 min) so fresh same-day rows replace
            # the "recent activity" names as soon as the data feed recovers, instead
            # of holding stale names for the full 15-min TTL.
            from datetime import timedelta as _td
            app._unusual_calls_cache_ts = _dt.now() - _td(seconds=720)
        return jsonify(out)


@app.route("/stock-api/unusual-calls/microcap", methods=["GET"])
def unusual_calls_microcap():
    """Return micro/small-cap unusual call options from DB, newest first.
    "Today" (days=1) is the ET calendar day only — no silent fallback to older
    days. If the window is empty a background scan is kicked off so the next
    load has fresh data.
    On weekends / outside market hours: use a 5-day lookback so Friday's data
    stays visible through the weekend.
    """
    days_back = min(int(request.args.get("days", 1)), 30)
    # Widen to 5 days on weekends/after-hours so Friday's sweeps are visible
    if not _intraday_scan_allowed() and days_back <= 1:
        days_back = 5

    # "Today" (days=1) means the actual ET calendar day — NOT a rolling 24h
    # window. A rolling window bleeds yesterday's afternoon/evening signals into
    # "today" (e.g. checking at noon shows data from yesterday at noon onward).
    # Wider windows (3d/7d) stay as rolling look-backs, which is what they say.
    if days_back <= 1:
        _window_clause = ("last_seen >= (date_trunc('day', now() AT TIME ZONE 'America/New_York') "
                          "AT TIME ZONE 'America/New_York') AT TIME ZONE 'UTC'")
        _params: dict = {}
    else:
        _window_clause = "last_seen >= NOW() - (%(days)s || ' days')::INTERVAL"
        _params = {"days": days_back}

    _SEL = f"""
        SELECT ticker, price::float, strike::float, expiry, days_out,
               volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
               iv::float, urgency, cap_tier,
               first_seen AT TIME ZONE 'UTC' AS first_seen,
               last_seen  AT TIME ZONE 'UTC' AS last_seen
        FROM unusual_calls_microcap_log
        WHERE {_window_clause}
          AND expiry::date > (now() AT TIME ZONE 'America/New_York')::date
          AND cap_tier IN ('nano', 'micro', 'small')
        ORDER BY prem DESC
        LIMIT 1000
    """
    try:
        with _psycopg2.connect(_DB_URL) as conn, conn.cursor() as cur:
            cur.execute(_SEL, _params)
            cols = [d[0] for d in cur.description]
            rows = [dict(zip(cols, r)) for r in cur.fetchall()]
            for r in rows:
                if r.get("first_seen"): r["first_seen"] = r["first_seen"].isoformat()
                if r.get("last_seen"):  r["last_seen"]  = r["last_seen"].isoformat()

        # Post-fetch stale check: rows exist but none are from today (ET) on a
        # trading day.  Happens when days_back > 1 is passed explicitly or the
        # weekend-widen kicked in and we're back on Monday with Friday rows.
        # On weekends/after-hours Friday rows are intentionally shown as fresh;
        # only flag stale when the market is (or was today) open.
        if rows and _intraday_scan_allowed():
            try:
                import datetime as _dtmc, pytz as _pzmc
                _et_now = _datetime.now(_pytz.timezone('America/New_York'))
                _today_et_str = _et_now.strftime('%Y-%m-%d')
                _most_recent_str = max(
                    r["last_seen"][:10] for r in rows if r.get("last_seen")
                )
                if _most_recent_str < _today_et_str:
                    rows = []   # force the stale-fallback path below to re-fetch
            except Exception:
                pass

        # Stale fallback: if the requested window is empty, return the most
        # recent scan from up to 14 days ago with stale=True so the tab shows
        # SOMETHING while the background scan runs, instead of a blank spinner.
        _stale = False
        _stale_note = None
        if not rows:
            try:
                with _psycopg2.connect(_DB_URL) as conn2, conn2.cursor() as cur2:
                    cur2.execute("""
                        SELECT ticker, price::float, strike::float, expiry, days_out,
                               volume, oi, vol_oi::float, prem::bigint, otm_pct::float,
                               iv::float, urgency, cap_tier,
                               first_seen AT TIME ZONE 'UTC' AS first_seen,
                               last_seen  AT TIME ZONE 'UTC' AS last_seen
                        FROM unusual_calls_microcap_log
                        WHERE last_seen >= NOW() - INTERVAL '14 days'
                          AND expiry::date > (now() AT TIME ZONE 'America/New_York')::date
                          AND cap_tier IN ('nano', 'micro', 'small')
                        ORDER BY prem DESC
                        LIMIT 500
                    """)
                    cols2 = [d[0] for d in cur2.description]
                    rows = [dict(zip(cols2, r)) for r in cur2.fetchall()]
                    if rows:
                        _stale = True
                        import datetime as _dt_mc
                        # Compute age BEFORE serializing timestamps
                        try:
                            _last_ts = max(r["last_seen"] for r in rows if r.get("last_seen"))
                            if _last_ts:
                                _last_ts_utc = _last_ts if _last_ts.tzinfo else _last_ts.replace(tzinfo=_dt_mc.timezone.utc)
                                _ago_h = (_dt_mc.datetime.now(_dt_mc.timezone.utc) - _last_ts_utc).total_seconds() / 3600
                                _stale_note = f"Showing signals from ~{int(_ago_h)}h ago — live scan in progress"
                        except Exception:
                            _stale_note = "Showing recent signals — live scan in progress"
                        for r in rows:
                            if r.get("first_seen"): r["first_seen"] = r["first_seen"].isoformat()
                            if r.get("last_seen"):  r["last_seen"]  = r["last_seen"].isoformat()
            except Exception as _se:
                print(f"[microcap] stale fallback error: {_se}")

        # If still empty, kick off a background scan so the next load has data
        if not rows:
            import threading as _thr
            _mc_lock = getattr(app, "_mc_autoscan_lock", None)
            if _mc_lock is None:
                app._mc_autoscan_lock = _thr.Lock()
                _mc_lock = app._mc_autoscan_lock
            if _mc_lock.acquire(blocking=False):
                def _bg_scan():
                    try:
                        hits = _run_microcap_options_scan()
                        _save_microcap_calls_to_db(hits)
                        print(f"[microcap_auto] background scan complete → {len(hits)} signals")
                    except Exception as _e:
                        print(f"[microcap_auto] scan error: {_e}")
                    finally:
                        _mc_lock.release()
                _thr.Thread(target=_bg_scan, daemon=True).start()

        return jsonify({"signals": rows, "total": len(rows),
                        "scan_triggered": not rows,
                        "stale": _stale,
                        "stale_note": _stale_note})
    except Exception as e:
        return jsonify({"error": str(e), "signals": [], "total": 0}), 500


