@app.route("/stock-api/gamma-pressure", methods=["GET"])
def gamma_pressure_endpoint():
    """
    Return recent gamma pressure signals sorted by score desc.
    ?date=YYYY-MM-DD  → filter to specific date (default: last 3 days)
    ?limit=N          → max rows (default 60)
    """
    try:
        import psycopg2, os as _os
        date_arg = request.args.get("date")
        limit    = min(int(request.args.get("limit", 60)), 200)

        with psycopg2.connect(_os.environ["DATABASE_URL"]) as conn, conn.cursor() as cur:
            if date_arg:
                cur.execute("""
                    SELECT ticker, price, price_change_pct, fir, fsd, float_shares, float_m,
                           call_volume, avg_delta, vol_oi, top_strike, top_strike_expiry,
                           score, sms_sent, alerted_at::TEXT, alert_date::TEXT
                    FROM gamma_pressure_alerts
                    WHERE alert_date = %s
                    ORDER BY score DESC LIMIT %s
                """, (date_arg, limit))
            else:
                cur.execute("""
                    SELECT ticker, price, price_change_pct, fir, fsd, float_shares, float_m,
                           call_volume, avg_delta, vol_oi, top_strike, top_strike_expiry,
                           score, sms_sent, alerted_at::TEXT, alert_date::TEXT
                    FROM gamma_pressure_alerts
                    WHERE alert_date >= (now() AT TIME ZONE 'America/New_York')::date - 3
                    ORDER BY score DESC LIMIT %s
                """, (limit,))

            cols = [d[0] for d in cur.description]
            rows = [dict(zip(cols, r)) for r in cur.fetchall()]

            cur.execute("""
                SELECT MAX(alerted_at)::TEXT
                FROM gamma_pressure_alerts
                WHERE alert_date = (now() AT TIME ZONE 'America/New_York')::date
            """)
            last_scan = (cur.fetchone() or [None])[0]

        return jsonify({"signals": rows, "count": len(rows), "last_scan": last_scan})
    except Exception as e:
        return jsonify({"signals": [], "count": 0, "last_scan": None, "error": str(e)}), 500


@app.route("/stock-api/oi-accumulation", methods=["GET"])
def oi_accumulation_endpoint():
    """
    Return OI accumulation signals: compare yesterday vs day-before snapshots.
    ?days=N  → how many days back to compare (default 1 = yesterday vs day before)
    """
    try:
        days_back = int(request.args.get("days", 1))
        rows, day1, day2 = _get_oi_accumulation_signals(days_back=days_back)
        # If the default comparison (most recent pair) has 0 overlap due to rotating
        # priority pools, auto-fall back one period to find the nearest pair with data.
        if not rows and days_back == 1:
            rows2, day1_2, day2_2 = _get_oi_accumulation_signals(days_back=2)
            if rows2:
                rows, day1, day2 = rows2, day1_2, day2_2
        signals = []
        for r in rows:
            ticker, price, strike, expiry, oi_t, oi_y, oi_chg, oi_pct, otm, days = r
            signals.append({
                "ticker": ticker, "price": float(price or 0),
                "strike": float(strike), "expiry": str(expiry),
                "oi_today": int(oi_t), "oi_yesterday": int(oi_y),
                "oi_change": int(oi_chg), "oi_pct_change": float(oi_pct or 0),
                "otm_pct": float(otm or 0), "days_out": int(days or 0),
            })
        # Return snapshot dates and the specific dates being compared
        import psycopg2, os as _os
        with psycopg2.connect(_os.environ["DATABASE_URL"]) as conn, conn.cursor() as cur:
            cur.execute("""
                SELECT DISTINCT snapshot_date::TEXT
                FROM oi_daily_snapshot
                ORDER BY snapshot_date DESC LIMIT 10
            """)
            dates = [r[0] for r in cur.fetchall()]
        return jsonify({
            "signals": signals, "count": len(signals), "snapshot_dates": dates,
            "compared_day1": day1, "compared_day2": day2,
        })
    except Exception as e:
        return jsonify({"signals": [], "count": 0, "snapshot_dates": [], "error": str(e)}), 500


@app.route("/stock-api/conviction-stack", methods=["GET"])
def conviction_stack_endpoint():
    """
    5-layer unified conviction scanner.
    Returns tickers ranked by multi-signal squeeze probability score (0-10 pts).
    8+ pts = ~90% confidence the stock is being positioned for a squeeze.
    """
    from datetime import datetime as _stk_dt
    _cs_stk_cache = getattr(app, "_cs_stk_cache", None)
    _cs_stk_ts    = getattr(app, "_cs_stk_ts",    None)
    if _cs_stk_cache and _cs_stk_ts and (_stk_dt.now() - _cs_stk_ts).total_seconds() < 600:
        return jsonify(_cs_stk_cache)

    def _bg_stk():
        if getattr(app, "_stk_scanning", False):
            return
        app._stk_scanning = True
        try:
            _results = _run_five_layer_conviction(max_tickers=CONVICTION_STACK_MAX)
            _out = {"results": _results, "count": len(_results),
                    "source": "free_yfinance", "universe_count": len(_results)}
            app._cs_stk_cache = _out
            app._cs_stk_ts    = _stk_dt.now()
        except Exception as _e:
            import traceback as _tb
            print(f"[conviction-stack] bg error: {_e}")
            _tb.print_exc()
        finally:
            app._stk_scanning = False

    import threading as _stk_thr
    if not getattr(app, "_stk_scanning", False):
        _stk_thr.Thread(target=_bg_stk, daemon=True).start()
    if _cs_stk_cache:
        return jsonify({**_cs_stk_cache, "stale": True})
    # No in-memory cache — serve last stored snapshot from DB while live scan runs
    try:
        import psycopg2 as _pg_cs_fb
        with _pg_cs_fb.connect(_DB_URL) as _c_cs_fb, _c_cs_fb.cursor() as _cu_cs_fb:
            _cu_cs_fb.execute("""
                SELECT ticker, total_pts, conviction_pct, label, price,
                       layers, meta, rank, universe_count, source, snap_date
                FROM conviction_stack_watchlist
                ORDER BY snap_date DESC, rank ASC
                LIMIT 150
            """)
            _cs_cols_fb = [d[0] for d in _cu_cs_fb.description]
            _cs_rows_fb = _cu_cs_fb.fetchall()
        if _cs_rows_fb:
            _cs_db_results = []
            for _r_fb in _cs_rows_fb:
                _d_fb = dict(zip(_cs_cols_fb, _r_fb))
                _cs_db_results.append({
                    "ticker":         _d_fb["ticker"],
                    "total_pts":      float(_d_fb["total_pts"] or 0),
                    "conviction_pct": int(_d_fb["conviction_pct"] or 0),
                    "label":          _d_fb["label"] or "",
                    "price":          float(_d_fb["price"] or 0),
                    "layers":         _d_fb["layers"] if isinstance(_d_fb["layers"], dict) else {},
                    "meta":           _d_fb["meta"]   if isinstance(_d_fb["meta"],   dict) else {},
                    "rank":           int(_d_fb["rank"] or 0),
                    "source":         "db",
                    "snap_date":      str(_d_fb["snap_date"]) if _d_fb["snap_date"] else None,
                })
            return jsonify({"results": _cs_db_results, "count": len(_cs_db_results),
                            "stale": True, "generating": True, "source": "db"})
    except Exception as _e_cs_fb:
        print(f"[conviction-stack] db fallback error: {_e_cs_fb}", file=_sys.stderr)
    return jsonify({"results": [], "count": 0, "generating": True})


@app.route("/stock-api/conviction-stack/score/<ticker>", methods=["GET"])
def conviction_stack_score_ticker_route(ticker):
    """On-demand: run ALL L1-L8 money-pressure layers for a SINGLE ticker, even if
    it has no OI/charm/gamma signal (which would normally keep it out of the heavy-
    fetch 'active' set). Returns the full layer breakdown so any name can be scored."""
    try:
        t = (ticker or "").strip().upper()
        if not t:
            return jsonify({"error": "no ticker"}), 400
        results = _run_five_layer_conviction(max_tickers=CONVICTION_STACK_MAX, force_tickers=[t])
        match = next((r for r in results if r["ticker"] == t), None)
        if not match:
            return jsonify({"ticker": t, "found": False, "source": "free_yfinance",
                            "note": "No money-pressure signal on this ticker right now."})
        return jsonify({"ticker": t, "found": True, "source": "free_yfinance", **match})
    except Exception as e:
        import traceback
        return jsonify({"ticker": ticker, "error": str(e),
                        "trace": traceback.format_exc()}), 500


